/**
 * 负责首夜开局设置的确定序列：盗贼／千面人、野孩子、孤独少女、鬼魂新娘。
 * 输入为现场读取 World、网关、事件和板子的查询，以及原 provider、日期和唯一当前性回调；
 * 输出为全部准备通过，或在首个未准备完成／失效步骤之后立即返回 false。异常原样向上抛出。
 * 组合只装配原窗口并串行交还原执行 Promise；选择、库存、接受权限和 finally 关闭仍由各机制拥有。
 * 不缓存 World 或提前读取构造参数；成功末尾没有额外当前性查询，也不推进阶段或生成快照。
 */
import type { GameEvent, ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import type { ActionProvider } from "../core/domain/actions";
import type { World } from "../core/domain/world";
import type { ToolGateway } from "../game/gateway/tool_gateway";
import {
  InitialIdentitySetupWindow,
  initialIdentitySetupReady,
  initialIdentityKind,
} from "../game/mechanisms/roles/initial_identity/ports";
import { WildChildSetupWindow, wildChildReady } from "../game/mechanisms/roles/wild_child/ports";
import { LonelyGirlSetupWindow, lonelyGirlReady } from "../game/mechanisms/roles/lonely_girl/ports";
import { GhostBrideSetupWindow, ghostBrideReady } from "../game/mechanisms/roles/ghost_bride/ports";

/** 查询只读取原调用点；事件数组与板子引用交给窗口，不产生新授权或状态镜像。 */
export interface GameSetupRuntime {
  world(): World;
  toolGateway(): ToolGateway;
  events(): GameEvent[];
  config(): ReadonlyBoardConfig;
}

export function* prepareGameSetup(
  runtime: GameSetupRuntime,
  actionProvider: ActionProvider,
  nightDay: number,
  nightIsCurrent: () => boolean,
): Generator<Promise<boolean>, boolean, boolean> {
  // 没有待设置窗口时同步结束；只在原 execute 的 Promise 处暂停，不增加 helper 完成等待。
  // 每个 new 先查找原类，再按原顺序读取参数；execute 仍使用该实例作为 receiver。
  if (!initialIdentitySetupReady(runtime.world())) {
    const ready = yield new InitialIdentitySetupWindow(
      runtime.world(),
      runtime.toolGateway(),
      runtime.events(),
      initialIdentityKind(runtime.world())!,
    ).execute(runtime.config(), actionProvider, nightDay, nightIsCurrent);
    if (!ready || !nightIsCurrent()) return false;
  }
  if (!wildChildReady(runtime.world())) {
    const ready = yield new WildChildSetupWindow(
      runtime.world(),
      runtime.toolGateway(),
      runtime.events(),
    ).execute(runtime.config(), actionProvider, nightDay, nightIsCurrent);
    if (!ready || !nightIsCurrent()) return false;
  }
  if (!lonelyGirlReady(runtime.world())) {
    const ready = yield new LonelyGirlSetupWindow(
      runtime.world(),
      runtime.toolGateway(),
      runtime.events(),
    ).execute(runtime.config(), actionProvider, nightDay, nightIsCurrent);
    if (!ready || !nightIsCurrent()) return false;
  }
  if (!ghostBrideReady(runtime.world())) {
    const ready = yield new GhostBrideSetupWindow(
      runtime.world(),
      runtime.toolGateway(),
      runtime.events(),
    ).execute(runtime.config(), actionProvider, nightDay, nightIsCurrent);
    if (!ready || !nightIsCurrent()) return false;
  }
  return true;
}

/**
 * 提供野孩子准备状态、夜间单元和原生命死亡标记的公开入口。输入保留原 World、日期和玩家序号；
 * 输出是原准备结果、关闭能力或绑定上的死亡标记。死亡标记在实际 Alive 修改之前写入，
 * 权限与失败、关闭状态由具体生命周期所有者校验。本入口不复制状态、不修改阵营，
 * 已提交整波的具体贡献仍按首次榜样死亡和原生命验证转换，在梦记录／遗言前运行；
 * 不是晚 deathHook 或新的死亡提交器，失败保留榜样事实及原已提交前缀。
 * 玩家知识及请求 scope／工具读取仍使用原函数绑定，不重新捕获榜样或生成死亡授权。
 */
export { hasActiveWildChild, wildChildReady, hasWildChildNightCommit, openWildChildNight } from "./lifecycle";

export { recordWildChildDeathCommit } from "./lifecycle";

/** 具名登记同一完整 owner 函数，不包装调用、不复制榜样绑定或重新判断生命。 */
export { resolveWildChildDeathWave } from "./lifecycle";

export { projectWildChild } from "./lifecycle";

export { wildChildRequestScope } from "./lifecycle";

export { readWildChildTool } from "./state";

/** 开局组合使用同一准备类绑定；具体窗口仍拥有选择校验、提交与失败关闭。 */
export { WildChildSetupWindow } from "./setup";

/**
 * 单元测试验证开局组合的现场读取、构造失败前缀及 await 后取消短路。
 * 输入为真实空 World、真实盗贼牌库／野孩子绑定和手写抛错查询；输出依据字面轨迹与原状态。
 * 机制执行及 finally 关闭使用原 owner，不运行整局或模型，不用待测函数生成预期或模拟许可。
 */
import { expect, test, spyOn } from "bun:test";
import { Role, type GameEvent } from "@ai-werewolf-arena/game-contract";
import { World } from "../../../src/core/domain/world";
import { ToolGateway } from "../../../src/game/gateway/tool_gateway";
import { prepareGameSetup, type GameSetupRuntime } from "../../../src/rulesets/game-setup";
import {
  installInitialIdentityDeal,
  initialIdentitySetupReady,
} from "../../../src/game/mechanisms/roles/initial_identity/deal";
import { bootstrapGame } from "../../../src/app/bootstrap";
import {
  wildChildBinding,
  hasActiveWildChild,
} from "../../../src/game/mechanisms/roles/wild_child/lifecycle";
import { foxBoard } from "../../support/features/cursed-fox/builders/scenario";
import { WildChildSetupWindow } from "../../../src/game/mechanisms/roles/wild_child/ports";

/** 测试调用方只消费组合交还的原窗口 Promise，完成值本身不再构成等待。 */
async function finishSetup(...args: Parameters<typeof prepareGameSetup>): Promise<boolean> {
  const sequence = prepareGameSetup(...args);
  let step = sequence.next();
  while (!step.done) step = sequence.next(await step.value);
  return step.value;
}

function unreadRuntime(world: World, trace: string[]): GameSetupRuntime {
  return {
    world() {
      trace.push("world");
      return world;
    },
    toolGateway() {
      trace.push("gateway");
      throw new Error("unexpected_gateway");
    },
    events() {
      trace.push("events");
      throw new Error("unexpected_events");
    },
    config() {
      trace.push("config");
      throw new Error("unexpected_config");
    },
  };
}

test("ready setup checks four live Worlds and does not call current at the successful tail", async () => {
  const trace: string[] = [];
  const ready = await finishSetup(
    unreadRuntime(new World(), trace),
    {
      async getAction() {
        throw new Error("unexpected_provider");
      },
    },
    1,
    () => {
      trace.push("current");
      return false;
    },
  );
  expect(ready).toBe(true);
  expect(trace).toEqual(["world", "world", "world", "world"]);
});

test("an initial constructor argument failure preserves only the earlier reads and pending deal", async () => {
  const world = new World(),
    trace: string[] = [],
    failure = new Error("original_gateway_failure");
  installInitialIdentityDeal(world, [Role.Villager, Role.Villager], []);
  const runtime = unreadRuntime(world, trace);
  runtime.toolGateway = () => {
    trace.push("gateway");
    throw failure;
  };
  await expect(
    prepareGameSetup(
      runtime,
      {
        async getAction() {
          throw new Error("unexpected_provider");
        },
      },
      1,
      () => {
        trace.push("current");
        return true;
      },
    ),
  ).rejects.toBe(failure);
  expect(trace).toEqual(["world", "world", "gateway"]);
  expect(initialIdentitySetupReady(world)).toBe(false);
});

test("a real Wild Child cancellation stops after its own current check and preserves lifecycle closure", async () => {
  const roles = [Role.WildChild, Role.Wolf, Role.Wolf, Role.Seer, Role.Witch, Role.Hunter];
  const config = foxBoard(roles),
    game = bootstrapGame(config, { fixedRoles: roles });
  const trace: string[] = [],
    events: GameEvent[] = [],
    gateway = new ToolGateway();
  let active = true;
  const ready = await finishSetup(
    {
      world() {
        trace.push("world");
        return game.world;
      },
      toolGateway() {
        trace.push("gateway");
        return gateway;
      },
      events() {
        trace.push("events");
        return events;
      },
      config() {
        trace.push("config");
        return game.boardConfig;
      },
    },
    {
      async getAction() {
        trace.push("provider");
        active = false;
        return { name: "choose_wild_model", args: { target_id: 2 } };
      },
    },
    1,
    () => {
      trace.push("current");
      return active;
    },
  );
  expect(ready).toBe(false);
  // 原请求绑定也会复验当前性；取消后的窗口复验只读一次，组合的 OR 不再调用它。
  expect(trace).toEqual([
    "world",
    "world",
    "world",
    "gateway",
    "events",
    "config",
    "current",
    "current",
    "current",
    "provider",
    "current",
  ]);
  expect(wildChildBinding(game.world)?.setup).toBe("cancelled");
  expect(hasActiveWildChild(game.world)).toBe(false);
  expect(events).toEqual([]);
});

test("synchronous setup has no microtask boundary when every step is ready", async () => {
  const trace: string[] = [];
  queueMicrotask(() => trace.push("queued"));
  const sequence = prepareGameSetup(
    unreadRuntime(new World(), trace),
    {
      async getAction() {
        throw new Error("unexpected_provider");
      },
    },
    1,
    () => {
      trace.push("current");
      return true;
    },
  );
  expect(trace).toEqual([]);
  expect(sequence.next()).toEqual({ done: true, value: true });
  trace.push("complete");
  expect(trace).toEqual(["world", "world", "world", "world", "complete"]);
  await Promise.resolve();
  expect(trace.at(-1)).toBe("queued");
});

test("a yielded original window resumes guards synchronously without an extra completion Promise", async () => {
  const roles = [Role.WildChild, Role.Wolf, Role.Wolf, Role.Seer, Role.Witch, Role.Hunter];
  const game = bootstrapGame(foxBoard(roles), { fixedRoles: roles });
  const trace: string[] = [],
    events: GameEvent[] = [],
    gateway = new ToolGateway();
  const provider = {
    async getAction() {
      return null;
    },
  };
  const current = () => {
    trace.push("current");
    return true;
  };
  let release!: (value: boolean) => void;
  const originalPromise = new Promise<boolean>((resolve) => {
    release = resolve;
  });
  // 仅替换窗口结果来观察组合的暂停边界；不模拟选择规则、授权或库存提交。
  const spy = spyOn(WildChildSetupWindow.prototype, "execute").mockImplementation(function (
    this: WildChildSetupWindow,
    config,
    actualProvider,
    day,
    isCurrent,
  ) {
    trace.push("execute");
    expect(config).toBe(game.boardConfig);
    expect(actualProvider).toBe(provider);
    expect(day).toBe(1);
    expect(isCurrent).toBe(current);
    return originalPromise;
  });
  try {
    const sequence = prepareGameSetup(
      {
        world() {
          trace.push("world");
          return game.world;
        },
        toolGateway() {
          trace.push("gateway");
          return gateway;
        },
        events() {
          trace.push("events");
          return events;
        },
        config() {
          trace.push("config");
          return game.boardConfig;
        },
      },
      provider,
      1,
      current,
    );
    const step = sequence.next();
    expect(step.done).toBe(false);
    expect(step.value).toBe(originalPromise);
    expect(trace).toEqual(["world", "world", "world", "gateway", "events", "config", "execute"]);
    release(true);
    const ready = await originalPromise;
    queueMicrotask(() => trace.push("queued"));
    expect(sequence.next(ready)).toEqual({ done: true, value: true });
    trace.push("complete");
    expect(trace.slice(-4)).toEqual(["current", "world", "world", "complete"]);
    await Promise.resolve();
    expect(trace.at(-1)).toBe("queued");
  } finally {
    spy.mockRestore();
  }
});
